#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using i128 = __int128;
const int MAXN = 1000005;
const int MODA = 998244353;
const int MODB = 1000000007;
int p10[15];
string gd[MAXN];
int N, num;
vector<string> lv[7];
vector<int> ok[7][7];
int sm[7][7];
const ll INF = 1e18;

int str2int(string s) {
    int r = 0;
    for (char c : s) r = r * 10 + (c - '0');
    return r;
}

i128 calc(string cur, int mx) {
    if (mx == -1) return 0;
    int L = mx / 2, R = mx - L;
    if (mx == 1) L = 1, R = 0;
    i128 res = (num - str2int(cur) + MODA * MODA) % MODA;
    num++;
    for (string lf : lv[L]) {
        res += (-str2int(cur + lf) + num + MODA * MODA) % MODA;
        num++;
        if ((int)lf.size() == L) {
            int c = str2int(cur + lf) % MODA;
            for (int o = 1; o <= R; ++o) {
                int cnst = (-c * p10[o] + num + MODA * MODA) % MODA;
                int pos = lower_bound(ok[R][o].begin(), ok[R][o].end(), MODA - cnst) - ok[R][o].begin();
                res += (int)ok[R][o].size() * cnst + sm[R][o] - MODA * ((int)ok[R][o].size() - pos);
            }
            num += (int)lv[R].size();
        }
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    N = to_string(n).size();
    p10[0] = 1;
    for (int i = 1; i <= 14; ++i) p10[i] = p10[i-1] * 10;
    string s = to_string(n);
    string cur = "";
    for (int i = 0; i < MAXN; ++i) {
        gd[i] = to_string(i);
        string now = gd[i];
        while ((int)now.size() <= 6) {
            lv[(int)now.size()].push_back(now);
            now = "0" + now;
        }
    }
    for (int i = 1; i <= 6; ++i) {
        for (auto key : lv[i-1]) lv[i].push_back(key);
        sort(lv[i].begin(), lv[i].end());
        for (int j = 0; j < (int)lv[i].size(); ++j) {
            ok[i][lv[i][j].size()].push_back((j - stoi(lv[i][j]) + MODA) % MODA);
        }
        for (int j = 1; j <= i; ++j) {
            sort(ok[i][j].begin(), ok[i][j].end());
            for (auto key : ok[i][j]) sm[i][j] += key;
        }
    }
    vector<pair<string, int>> Q;
    for (int i = 0; i < (int)s.size(); ++i) {
        for (int j = 0; j <= 9; ++j) {
            if (j == s[i] - '0') continue;
            if (i == 0 && j == 0) continue;
            cur += char('0' + j);
            if (j <= s[i] - '0') {
                Q.push_back({cur, (int)s.size() - i - 1});
            } else {
                Q.push_back({cur, (int)s.size() - i - 2});
            }
            cur.pop_back();
        }
        cur += s[i];
        Q.push_back({cur, 0});
    }
    num = 1;
    i128 ans = 0;
    sort(Q.begin(), Q.end());
    for (auto key : Q) {
        if (s[(int)key.first.size() - 1] == key.first.back()) {
            ans += (-str2int(key.first) + num + MODA * MODA) % MODA;
            num += 1;
            continue;
        }
        ans += calc(key.first, key.second);
    }
    ans %= MODB;
    cout << (long long)ans;
    return 0;
}
